import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
export async function authorize_member_join(
  connection: api.IConnection,
  props: {
    body?: DeepPartial<ITodoUser.IJoin>;
  },
): Promise<ITodoUser.IAuthorized> {
  const joinInput = {
    email:
      props.body?.email ?? `${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: props.body?.password ?? RandomGenerator.alphaNumeric(16),
    name: props.body?.name ?? RandomGenerator.name(),
  } satisfies ITodoUser.IJoin;
  return await api.functional.auth.user.join(connection, { body: joinInput });
}

